action.code:
if (hash < 0.0f || hash > 1.0f) {
    throw std::out_of_range("Hash value must be in the range [0, 1]");
}

SharedLock lk(partition_map_mx_);
if (partition_to_bucket.empty()) {
    return nullptr;
}

auto it = partition_to_bucket.upper_bound(hash);
if (it == partition_to_bucket.end()) {
    it = partition_to_bucket.begin();
}

return it->second;

